import React from 'react';
import s from './Dialogs.module.css'
import DiologsItems from './DialogsItem/DialogsItem';
import Message from './Message/Message';
import { Field, Form, Formik } from 'formik';


const Dialogs = (props) => {
    let state = props.DialogsPage;

    let messageElements = state.messagesData.map((m, index) => <Message message={m.message} id={m.id} key={index} />);
    let newMessageElements = React.createRef();
    let dialogsElement = state.dialogsData.map((d, index) => <DiologsItems name={d.name} id={d.id} key={index} />);
    let NewMessageBody = state.NewMessageBody;

    let onSendMessage = () => {
        props.onSendMessage()
    }
    let onNewMessageChange = (e) => {
        let body = e.target.value;
        props.updateNewMessageBody(body);
    }

    return (
        <div className={s.dialogs}>
            <div className={s.dialogs_items}>
                <div className={s.users_header}>
                    Messages
                </div>
                {dialogsElement}
            </div>
            <div className={s.messages}>
                <div className={s.chat_header}>
                    <div className={s.chat_avatar}>
                        K
                    </div>
                    <div>
                        <div className={s.chat_name}>
                            Kostya
                        </div>
                        <div className={s.online}>
                            Online
                        </div>
                    </div>
                </div>
                <div className={s.chat_body}>
                    {messageElements}
                </div>
                <div className={s.chat_input_area}>
                    <Formik
                        initialValues={{
                            message: ""
                        }}
                        onSubmit={async (values, { setSubmitting }) => {
                        }}
                    >
                        {({ isSubmitting }) => (
                            <Form className={s.form}>

                                <Field
                                    className={s.input}
                                    value={NewMessageBody}
                                    innerRef={newMessageElements}
                                    type="text"
                                    name="message"
                                    placeholder="Write a message..."
                                    onChange={onNewMessageChange}
                                />
                                <button
                                    className={s.button}
                                    onClick={onSendMessage}
                                    type="submit"
                                    disabled={isSubmitting}
                                >
                                    Send
                                </button>
                            </Form>
                        )}
                    </Formik>
                </div>
            </div>
        </div>
    )
}
export default Dialogs;